// EventClassOf returns the class that the catalog gives the event name, and false for a name the catalog does not declare.
func EventClassOf(name string) (Class, bool) {
	if class, found := eventClasses[name]; found {
		return class, true
	}
	for _, family := range eventClassFamilies {
		if len(name) > len(family.prefix) && name[:len(family.prefix)] == family.prefix && familyTail(name[len(family.prefix):]) {
			return family.class, true
		}
	}
	return "", false
}

// familyTail reports whether text is one or more characters of `a-z`, `0-9`, `_` and `.`, which a placeholder stands for.
func familyTail(text string) bool {
	for index := 0; index < len(text); index++ {
		c := text[index]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_' || c == '.') {
			return false
		}
	}
	return true
}
